select cast(current_timestamp(6) as datetime)  as ts, CURRENT_SCHEMA, DIGEST_TEXT, SQL_TEXT,   FROM_UNIXTIME((UNIX_TIMESTAMP(NOW()) - (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'UPTIME')) + (TIMER_START / 1000000000000)) AS start_time,  FROM_UNIXTIME((UNIX_TIMESTAMP(NOW()) - (SELECT VARIABLE_VALUE FROM performance_schema.global_status WHERE VARIABLE_NAME = 'UPTIME')) + (TIMER_END / 1000000000000)) AS end_time, (TIMER_WAIT / 10000000000) AS EXECUTION_TIME  from performance_schema.events_statements_history\
